   "codice": "extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve caricarsi correttamente"):
		return
	var door := find_by_name(main, "Door")
	if not check("door", door != null, "Nella scena principale deve esserci il nodo Door"):
		return
	var col_shape := find_by_class(door, "CollisionShape3D") as CollisionShape3D
	if not check("shape", col_shape != null, "Il nodo Door deve contenere una CollisionShape3D"):
		return
	var has_interact := has_function(door, "interact")
	if not check("has_interact", has_interact, "Il nodo Door deve avere un metodo interact()"):
		return
	check("init_enabled", col_shape.disabled == false, "All'inizio la collisione della porta deve essere attiva (disabled == false)")
	call_if_exists(door, "interact")
	check("toggle_disabled", col_shape.disabled == true, "Dopo la prima interazione la collisione della porta deve essere disattivata (disabled == true)")
	call_if_exists(door, "interact")
	check("toggle_enabled", col_shape.disabled == false, "Dopo la seconda interazione la collisione della porta deve tornare attiva (disabled == false)")
"
  }
